const rows = $input.all();
const tokenRow = rows.find(r => r.json.key === 'THRUUU_TOKEN');
const expiresRow = rows.find(r => r.json.key === 'THRUUU_EXPIRES_AT' || r.json.key === 'THRUUU_TOKEN');

if (!tokenRow) {
  return [{ json: { token: '', isExpired: true, remainingHours: 0, expiresAt: '', error: 'THRUUU_TOKEN not found in 09_CONFIG' } }];
}

const token = tokenRow.json.value || '';
const expiresAt = tokenRow.json.expires_at || '';
const now = Date.now();
const expires = expiresAt ? new Date(expiresAt).getTime() : 0;
const remainingMs = expires - now;
const remainingHours = expires > 0 ? Math.round(remainingMs / 3600000) : -1;

return [{
  json: {
    token,
    expiresAt,
    remainingHours,
    isExpiringSoon: remainingHours < 2,
    isExpired: remainingMs < 0,
    alert: remainingHours < 2
  }
}];

const r = $input.first().json;
const status = r.statusCode || r.status || 0;
const body = r.body || r;
const isAuthError = status === 401 ||
  (typeof body === 'object' && JSON.stringify(body).toLowerCase().includes('not supplied')) ||
  (typeof body === 'object' && JSON.stringify(body).toLowerCase().includes('unauthorized'));

return [{ json: { status, isAuthError, body, tokenOk: !isAuthError } }];
